// Normalizar datos del lead para Evolution API
const lead = $input.first().json.body || $input.first().json;

const nombre = lead.nombre || 'Cliente';
const whatsappClean = (lead.whatsapp || '').replace(/\D/g, '');
const numberFormatted = whatsappClean.startsWith('52') ? whatsappClean : '52' + whatsappClean;
const nombreNegocio = lead.nombreNegocio || 'Negocio';
const dedicacion = lead.dedicacion || 'No especificado';
const tienePagina = lead.tienePagina || 'No';
const urgencia = lead.urgencia || 'Esta semana';
const socialLink = lead.socialLink || '';
const utm = lead.utm || {};

// Determinar Prioridad
let prioridad = 'MEDIA (Vista previa 24h)';
if (urgencia.toLowerCase().includes('semana')) {
  prioridad = 'ALTA (Llamar Hoy)';
} else if (urgencia.toLowerCase().includes('viendo')) {
  prioridad = 'BAJA (Guía 3 días)';
}

// Texto del mensaje de bienvenida por WhatsApp (Evolution API)
const textoMensaje = `Hola ${nombre} 👋, soy Mauricio de Idealy. Ya recibimos los datos de *${nombreNegocio}*. Mañana a primera hora te mando tu vista previa por este medio.\n\nSi tienes alguna duda previa, me puedes escribir directamente por aquí.`;

return {
  nombre,
  whatsappClean,
  numberFormatted,
  nombreNegocio,
  dedicacion,
  tienePagina,
  urgencia,
  prioridad,
  socialLink,
  utm_source: utm.source || 'Directo',
  utm_medium: utm.medium || '-',
  utm_campaign: utm.campaign || '-',
  gclid: utm.gclid || '-',
  textoMensaje,
  fechaRegistro: new Date().toISOString()
};
